def compute(vars):
    loans = vars["v1"]
    total_pledged_assets = vars["v2"]

    if total_pledged_assets == 0:
        return None

    ratio = loans / total_pledged_assets
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "loans": loans,
            "total_pledged_assets": total_pledged_assets,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
